-- Wave 8 step 2: invoices and metering records.
--
-- Generated by `prisma migrate diff` against the live database, then reduced to the two new models.
-- The full diff also carried drift from earlier waves that were applied by hand rather than by
-- migration; folding that in would make this migration responsible for changes it does not
-- describe, so it was deliberately left out.
--
-- Every id column is TEXT, read from information_schema rather than assumed. An earlier migration in
-- this repo assumed uuid and Postgres rejected the foreign keys outright -- when two tables meet, the
-- type is a fact about the existing tables, not a detail to infer.
--
-- The unique constraints are not idempotency. A webhook retry and a manual retry can both arrive for
-- one invoice, and a unique index only stops the second from erroring. The conditional update in the
-- service is what turns the second arrival into a no-op instead of an error.

-- CreateEnum
CREATE TYPE "InvoiceStatus" AS ENUM ('SIMULATED', 'PENDING', 'SETTLED', 'FAILED', 'EXPIRED');

-- CreateTable
CREATE TABLE "metering_records" (
    "id" TEXT NOT NULL,
    "tenantId" TEXT NOT NULL,
    "deviceId" TEXT NOT NULL,
    "periodStart" TIMESTAMP(3) NOT NULL,
    "quantity" INTEGER NOT NULL DEFAULT 0,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "metering_records_pkey" PRIMARY KEY ("id")
);

-- CreateTable
